// PRIVATE ROUTE101 ACTORS: audited ordinary gaps; not stock overrides.
#define SPRITE_HOENN_ZIGZAGOON_CHASE 26
#define SPRITE_HOENN_BIRCH_BAG 27

// These four ordinary-floor arrival anchors are destinations only.
// Field_GetWarpEventI still resolves them by index on map load.
if ((fieldSystem->location->mapId == MAP_LITTLEROOT_TOWN_TRAVEL
        && (i == 3 || i == 4) && x == 10 + (i - 3) && y == 2
        && fieldSystem->mapEvents->warp_events[i].x == x
        && fieldSystem->mapEvents->warp_events[i].z == y)
    || (fieldSystem->location->mapId == MAP_ROUTE_101_TRAVEL
        && (i == 2 || i == 3) && x == 10 + (i - 2) && y == 19
        && fieldSystem->mapEvents->warp_events[i].x == x
        && fieldSystem->mapEvents->warp_events[i].z == y)) {
    continue;
}

if (fieldSystem->location->mapId == MAP_ROUTE_101_TRAVEL
    && (i == 0 || i == 1)
    && GetScriptVar(Save_VarsFlags_Get(fieldSystem->saveData), VAR_HOENN_RESCUE_STATE) != HOENN_RESCUE_COMPLETE) {
    continue;
}

// Private opcode 854. Keep scene object IDs, graphics, and the map restriction
// fixed here; never apply this recovery command to other maps or object IDs.
BOOL ScrCmd_EnsureRoute101Actors(ScriptContext *ctx) {
    static const u16 sprites[3] = { 32, 26, 27 };
    FieldSystem *fieldSystem = ctx->fieldSystem;
    u16 *result = ScriptGetVarPointer(ctx);
    MapObjectManager *manager = fieldSystem->mapObjectManager;
    const ObjectEvent *events;
    LocalMapObject *objects;
    u32 eventCount;
    u32 objectCapacity;
    u32 activeCount = 0;
    u32 present = 0;
    u32 templates = 0;
    u32 missing;
    u32 i;

    *result = 0;
    if (fieldSystem->location->mapId != MAP_ROUTE_101_TRAVEL || manager == NULL) {
        return FALSE;
    }

    eventCount = Field_GetNumObjectEvents(fieldSystem);
    events = Field_GetObjectEvents(fieldSystem);
    if (eventCount != 3 || events == NULL) {
        return FALSE;
    }
    for (i = 0; i < eventCount; i++) {
        u16 id = events[i].id;
        if (id >= 3 || (templates & (1U << id)) != 0
            || events[i].eventFlag != 0 || events[i].scriptId == 0xFFFF
            || events[i].spriteId != sprites[id]) {
            return FALSE;
        }
        templates |= 1U << id;
    }
    if (templates != 7) {
        return FALSE;
    }

    objectCapacity = MapObjectManager_GetObjectCount(manager);
    objects = MapObjectManager_GetObjects(manager);
    if (objects == NULL) {
        return FALSE;
    }
    for (i = 0; i < objectCapacity; i++) {
        LocalMapObject *object = &objects[i];
        u32 id;
        if (!MapObject_CheckActive(object)) {
            continue;
        }
        activeCount++;
        id = MapObject_GetID(object);
        if (id >= 3) {
            continue;
        }
        if ((present & (1U << id)) != 0
            || MapObject_GetMapID(object) != MAP_ROUTE_101_TRAVEL
            || MapObject_CheckFlag25(object)
            || MapObject_GetSpriteID(object) != sprites[id]) {
            return FALSE;
        }
        present |= 1U << id;
    }
    missing = 3 - ((present & 1U) != 0) - ((present & 2U) != 0) - ((present & 4U) != 0);
    // The native save synchronizer asserts after consuming the last of its
    // 64 slots. Reserve one inactive slot in BOTH manager and saved objects.
    if (activeCount + missing >= objectCapacity || activeCount + missing >= 64) {
        return FALSE;
    }

    for (i = 0; i < 3; i++) {
        LocalMapObject *object;
        if ((present & (1U << i)) != 0) {
            continue;
        }
        object = MapObject_CreateFromObjectEventWithId(manager, i, eventCount,
            MAP_ROUTE_101_TRAVEL, events);
        if (object == NULL || !MapObject_CheckActive(object)
            || MapObjectManager_GetFirstActiveObjectByID(manager, i) != object
            || MapObject_GetMapID(object) != MAP_ROUTE_101_TRAVEL
            || MapObject_CheckFlag25(object)
            || MapObject_GetSpriteID(object) != sprites[i]) {
            return FALSE;
        }
    }
    *result = 1;
    return FALSE;
}

// Only the two lab exit lanes bypass the blocked outdoor door event. Keep
// town door warp 0 intact as the intentional north-facing lab entrance.
if (fieldSystem->location->mapId == MAP_HOENN_LAB_DEBUG
    && mapID == MAP_LITTLEROOT_TOWN_TRAVEL && warpID == 0) {
    Location *entrance = LocalFieldData_GetEntrancePosition(Save_LocalFieldData_Get(fieldSystem->saveData));
    int lane = entrance->warpId;
    if (entrance->mapId == MAP_HOENN_LAB_DEBUG && (lane == 0 || lane == 1)
        && entrance->x == 15 + lane && entrance->y == 21) {
        const WarpEvent *exit = Field_GetWarpEventI(fieldSystem, lane);
        int standingX = PlayerAvatar_GetXCoord(fieldSystem->playerAvatar);
        int standingZ = PlayerAvatar_GetZCoord(fieldSystem->playerAvatar);
        if (exit != NULL && exit->x == entrance->x && exit->z == entrance->y
            && exit->header == mapID && exit->anchor == 0
            && standingX == entrance->x
            && (standingZ == entrance->y
                || (standingZ == 20 && PlayerAvatar_GetFacingDirection(fieldSystem->playerAvatar) == DIR_SOUTH))) {
            warpID = -1; // Preserve explicit x/z in sub_02052F94.
            x = 7;
            y = 17;
            dir = DIR_SOUTH;
            transNo = 6; // Generic fade/entry; neither private map has animated door props.
        }
    }
}

// The generic SOUTH entry animates one extra tile after map load.
// Only the lab's explicit town arrival needs its fade without that step.
Location *entrance = LocalFieldData_GetEntrancePosition(Save_LocalFieldData_Get(fieldSystem->saveData));
if (fenv->transitionNo == 6
    && fieldSystem->location->mapId == MAP_LITTLEROOT_TOWN_TRAVEL
    && fenv->location.mapId == MAP_LITTLEROOT_TOWN_TRAVEL
    && fenv->location.warpId == -1
    && fenv->location.x == 7 && fenv->location.y == 17
    && fenv->location.direction == DIR_SOUTH
    && PlayerAvatar_GetXCoord(fieldSystem->playerAvatar) == 7
    && PlayerAvatar_GetZCoord(fieldSystem->playerAvatar) == 17
    && PlayerAvatar_GetFacingDirection(fieldSystem->playerAvatar) == DIR_SOUTH
    && entrance->mapId == MAP_HOENN_LAB_DEBUG
    && (entrance->warpId == 0 || entrance->warpId == 1)
    && entrance->x == 15 + entrance->warpId && entrance->y == 21) {
    // Native generic helper's SOUTH completion clears VISIBLE: the
    // renderer maps CheckVisible == 1 to sprite display flag 0.
    MapObject_SetVisible(mapObj, FALSE);
    NewFieldFadeEnvironment(man, FADE_BOTH_SCREENS, FADE_TYPE_BRIGHTNESS_IN,
                            FADE_TYPE_BRIGHTNESS_IN, 0, 6, 1, HEAP_ID_FIELD2);
} else {
    TaskManager_Call(man, ov01_021EA128, ov01_021E9C30());
}
